class APIKeyBase(SecurityBase):
    def __init__(self, not_authenticated_status_code: Optional[int] = None):
        self.not_authenticated_status_code = not_authenticated_status_code or HTTP_403_FORBIDDEN

    def check_api_key(self, api_key: Optional[str], auto_error: bool) -> Optional[str]:
        if not api_key:
            if auto_error:
                raise HTTPException(
                    status_code=self.not_authenticated_status_code, detail="Not authenticated"
                )
            return None
        return api_key

